declare(strict_types=1);

namespace Fuzz\Target;

use Error;
use SqlFormatter\Facade\Formatter;
use SqlSemantics\Facade\SchemaSemantics;
use Throwable;

/**
 * Every planned definition must survive analysis, writing and immutable composition.
 */
final class SchemaTarget
{
    public function __construct(private readonly SchemaSemantics $semantics, private readonly Formatter $compact, private readonly string $grammarVersion)
    {
    }

    /**
     * No generated input or semantic rejection is filtered out.
     */
    public function verify(string $sql, string $input): void
    {
        try {
            $definition = $this->semantics->analyze($sql);
            $before = serialize($definition);
            $printed = $definition->toString();
            if ($this->compact->format($sql) !== $this->compact->format(rtrim($printed, ';'))) {
                throw new Error('Schema reconstruction changed SQL.');
            }
            if ($this->semantics->analyze($printed)->toString() !== $printed) {
                throw new Error('Schema reconstruction is not stable.');
            }
            $empty = $definition->withStatements();
            $copy = $empty->append(...$definition->statements);
            if ($empty->statements !== [] || $copy->toString() !== $printed || serialize($definition) !== $before) {
                throw new Error('Schema composition changed an existing value.');
            }
            // Exercise real scripts, including DROP alongside CREATE and routine bodies.
            $script = 'DROP TABLE IF EXISTS schema_fuzz_previous; ' . $printed;
            $analyzed = $this->semantics->analyze($script);
            if ($this->semantics->analyze($analyzed->toString())->toString() !== $analyzed->toString()) {
                throw new Error('Schema script boundaries changed.');
            }
        } catch (Throwable $error) {
            throw new Error("Schema property failed\nGrammar: {$this->grammarVersion}\nInput (hex): " . bin2hex($input) . "\nSQL: {$sql}\n{$error->getMessage()}", 0, $error);
        }
    }
}
