    {
        foreach (Tree::outer($source, ['OptInherit', 'TableLikeClause', 'PartitionBoundSpec', 'TypedTableElementList']) as $inherited) {
            if ($inherited->tokens() !== []) {
                Tree::unsupported($inherited, 'catalog columns requiring another relation');
