    public function options(Node $source): array
    {
        return array_values(array_filter(Tree::outer($source, ['OptWith', 'OptTableSpace', 'OnCommitOption', 'OptAccessMethod', 'PartitionSpec']), static fn (Node $node): bool => $node->tokens() !== []));
