<?php

declare(strict_types=1);

namespace SqlSemantics\Facade;

use SqlSemantics\Core\Analysis\SchemaAnalyzer;
use SqlSemantics\Core\Dialect;
use SqlSemantics\Core\Schema as SchemaState;

/**
 * Reads the table state needed to analyze statements against known declarations.
 *
 * Schema describes state; Semantics describes SQL operations. Statements whose
 * resulting columns require query evaluation remain statement models.
 *
 * @visibility public
 * @example Reading state for statement binding
 *     $schema = new \SqlSemantics\Facade\Schema(\SqlSemantics\Platform\Sqlite\Dialect::Sqlite);
 *     $schema->analyze('CREATE TABLE t (id INTEGER)')->tables[0]->name // => 't'
 */
final class Schema
{
    private readonly SchemaAnalyzer $analyzer;

    /**
     * Selects the state declaration language, release and unqualified namespace.
     */
    public function __construct(Dialect $dialect, ?string $defaultSchema = null, ?string $grammarVersion = null)
    {
        $this->analyzer = new SchemaAnalyzer($dialect, $defaultSchema, $grammarVersion);
    }

    /**
     * Reads table declarations and DROP TABLE resets into an independent state.
     * @throws \SqlSemantics\Core\SemanticException When catalog facts conflict or cannot be resolved
     * @throws \SqlSemantics\Core\AnalysisException When declarations are outside the selected language
     */
    public function analyze(string ...$sql): SchemaState
    {
        return $this->analyzer->analyze(...$sql);
    }
}
<?php

declare(strict_types=1);

namespace SqlSemantics\Core\Analysis;

use SqlParser\Lexer\SourceException;
use SqlSemantics\Core\AnalysisException;
use SqlSemantics\Core\Ast\DialectParser;
use SqlSemantics\Core\Ast\Identifiers;
use SqlSemantics\Core\Ast\SchemaReader;
use SqlSemantics\Core\Dialect;
use SqlSemantics\Core\Schema;

/**
 * Resolves declaration SQL into immutable state used by statement binding.
 * @visibility SqlSemantics
 */
final class SchemaAnalyzer
{
    private readonly DialectParser $parser;
    private readonly string $defaultSchema;

    /**
     * Selects a language, release and default declaration namespace.
     */
    public function __construct(private readonly Dialect $dialect, ?string $defaultSchema = null, ?string $grammarVersion = null)
    {
        $this->defaultSchema = $defaultSchema ?? $dialect->platform()->defaultSchema();
        $this->parser = new DialectParser($dialect, $grammarVersion);
    }

    /**
     * Builds a closed table state without retaining parser nodes or SQL text.
     * @throws \SqlSemantics\Core\SemanticException When state facts conflict or cannot be resolved
     * @throws AnalysisException When declarations are outside the selected language
     */
    public function analyze(string ...$sql): Schema
    {
        try {
            return $this->read(...$sql);
        } catch (SourceException $error) {
            throw new AnalysisException($error->getMessage(), 0, $error);
        }
    }

    /**
     * Compatibility path preserving the original parser exception contract.
     * @throws \SqlSemantics\Core\SemanticException When state facts conflict or cannot be resolved
     * @throws SourceException When declarations are outside the selected language
     */
    public function read(string ...$sql): Schema
    {
        $trees = [];
        foreach ($sql as $text) {
            array_push($trees, ...$this->parser->parseScript($text));
        }
        $values = $this->dialect->platform()->values($this->parser->version());
        $tables = (new SchemaReader(new Identifiers($this->dialect), $this->defaultSchema, $values))->read($trees);

        return new Schema($this->dialect, $tables, $this->defaultSchema, $this->parser->version());
    }
}
<?php

declare(strict_types=1);

namespace SqlSemantics\Core\Schema;

use InvalidArgumentException;
use SqlSemantics\Statement\Element;

/**
 * A typed generation clause, including identity options or its computed expression.
 * @visibility public
 * @example Accepting generated column facts
 *     $accept = static fn (\SqlSemantics\Core\Schema\ColumnGeneration $value): string => $value->kind->value;
 *     $accept instanceof \Closure // => true
 */
final class ColumnGeneration
{
    /**
     * An identity has no computation expression; virtual and stored columns do.
     * @throws InvalidArgumentException When supplied state violates its invariants
     */
    public function __construct(
        public readonly GenerationKind $kind,
        public readonly Element $clause,
        public readonly ?Element $expression,
    ) {
        Invariant::ensure(($kind === GenerationKind::Identity) === ($expression === null), 'Only an identity generation has no computation expression.');
        Invariant::elements($clause, $expression);
    }
}

